func buildXPEventThenLoader[Q orm.Loadable]() xpEventThenLoader[Q] {
	type CharacterLoadInterface interface {
		LoadCharacter(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}

	return xpEventThenLoader[Q]{
		Character: thenLoadBuilder[Q](
			"Character",
			func(ctx context.Context, exec bob.Executor, retrieved CharacterLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadCharacter(ctx, exec, mods...)
			},
		),
	}
}

// LoadCharacter loads the xpEvent's Character into the .R struct
func (o *XPEvent) LoadCharacter(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.Character = nil
	o.R.Loaded.Character = false

	related, err := o.Character(mods...).One(ctx, exec)
	if err != nil {
		return err
	}

	related.R.XPEvents = XPEventSlice{o}

	o.R.Character = related
	o.R.Loaded.Character = true
	return nil
}

// LoadCharacter loads the xpEvent's Character into the .R struct
func (os XPEventSlice) LoadCharacter(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	characters, err := os.Character(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.Character = nil
		o.R.Loaded.Character = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	xpEventByKey := make(map[int64][]*XPEvent, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		xpEventByKey[o.CharacterID] = append(xpEventByKey[o.CharacterID], o)
	}

	for _, rel := range characters {

		owners, ok := xpEventByKey[rel.ID]
		if !ok {
			continue
		}

		for _, o := range owners {

			// to-one: keep only the first matching child (matches the previous break)
			if o.R.Character != nil {
				continue
			}

			rel.R.XPEvents = append(rel.R.XPEvents, o)

			o.R.Character = rel

		}
	}

	return nil
}

type xpEventJoins[Q dialect.Joinable] struct {
	typ       string
	Character modAs[Q, characterColumns]
}

func (j xpEventJoins[Q]) aliasedAs(alias string) xpEventJoins[Q] {
	return buildXPEventJoins[Q](buildXPEventColumns(alias), j.typ)
}

func buildXPEventJoins[Q dialect.Joinable](cols xpEventColumns, typ string) xpEventJoins[Q] {
	return xpEventJoins[Q]{
		typ: typ,
		Character: modAs[Q, characterColumns]{
			c: Characters.Columns,
			f: func(to characterColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Characters.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.CharacterID),
					))
				}

				return mods
			},
		},
	}
}
